"""Project-bound reform workspace, reading the same state as MCP."""
REFORM_CSS = r"""
.rf-summary{display:grid;grid-template-columns:repeat(auto-fit,minmax(160px,1fr));gap:16px;margin:20px 0}.rf-summary dt{color:var(--muted,#64748b);font-size:13px}.rf-summary dd{margin:6px 0;font-size:18px;overflow-wrap:anywhere}.rf-nav{display:flex;flex-wrap:wrap;gap:8px;border-bottom:1px solid #dbe3ed;padding-bottom:12px;margin-bottom:18px}.rf-task{padding:16px 0;border-bottom:1px solid #e2e8f0}.rf-task p{margin:6px 0}.rf-workspace pre{white-space:pre-wrap;overflow-wrap:anywhere}.rf-workspace label{display:block;margin:14px 0}.rf-workspace input,.rf-workspace textarea,.rf-workspace select{display:block;width:100%;margin-top:6px;box-sizing:border-box}.rf-workspace .row{flex-wrap:wrap}.rf-workspace code{overflow-wrap:anywhere}.rf-conflict{display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:16px}
"""
REFORM_JS = r"""
async function rfList(project=S.proj,status='',after=0){
  stopPolls('reform-detail');const route=location.hash,seq=S.reformRead=(S.reformRead||0)+1;
  S.svc='reform';paintTabs('reform');setProj(project);paintSel();const alive=()=>route===location.hash&&seq===S.reformRead;
  const labels={draft:'草稿',active:'可推进',paused:'已暂停',blocked:'等待处理',accepted:'当前版本已整体验收',cancelled:'已取消',archived:'已归档'};
  let d;try{d=await get('/api/projects/'+encodeURIComponent(project)+'/reforms?view=list&after='+after+'&limit=20&status='+encodeURIComponent(status)+'&archived='+(status==='archived'?'1':'0'))}catch(e){if(!alive())return;$('#main').innerHTML=pageHead('改造计划','')+`<div role="alert">加载失败：${h(e.message)} <button id="rfListRetry">重新加载</button></div>`;$('#rfListRetry')?.addEventListener('click',()=>rfList(project,status,after));return}
  if(!alive())return;S.rf=d;
  $('#main').innerHTML=pageHead('改造计划','',d.built&&accessCanWrite(project)?'<button class="primary" id="rfNew">新建改造计划</button>':'')+`<label for="rfListState">状态</label> <select id="rfListState"><option value="">活动计划</option>${Object.entries(labels).map(([k,v])=>`<option value="${k}" ${status===k?'selected':''}>${v}</option>`).join('')}</select><div id="rfForm" hidden></div>`+(d.items.length?d.items.map(p=>`<article class="rf-task"><div class="row"><h2 class="grow"><a href="${h(p.deep_link)}">${h(p.title)}</a></h2><span>${h(labels[p.state]||p.state)}</span></div><p>负责人 ${h(p.next_owner)} · ${h(p.batch_label)} · 已派发 ${p.counts.released} / ${p.counts.total} · 已验收 ${p.counts.business_accepted} / ${p.counts.total}</p><p>${h(p.blocked||'无已记录调度阻塞')} · 检查点 ${p.checkpoint?'#'+h(p.checkpoint.id):'未形成'}</p><p class="sub">状态更新 ${h(chinaTime(p.status_updated))}</p></article>`).join(''):'<div class="empty">没有符合当前筛选的计划。</div>')+`<div class="row"><button id="rfListPrev" ${after?'':'disabled'}>上一页</button><span>第 ${Math.floor(after/20)+1} 页</span><button id="rfListNext" ${d.has_more?'':'disabled'}>下一页</button></div>`;
  $('#rfListState').onchange=e=>rfList(project,e.target.value,0);$('#rfListPrev').onclick=()=>rfList(project,status,Math.max(0,after-20));$('#rfListNext').onclick=()=>rfList(project,status,d.next_cursor);$('#rfNew')?.addEventListener('click',rfForm);if(S.rfNew&&$('#rfNew')){S.rfNew=0;rfForm()}
  poll(()=>{if(alive()&&$('#rfForm')?.hidden)return rfList(project,status,after)},5000,'reform-detail');
}
async function rfWorkspace(project,id,tab='current'){
  stopPolls('reform-detail');
  const route=location.hash,seq=S.reformRead=(S.reformRead||0)+1,base='/api/projects/'+encodeURIComponent(project)+'/reforms',query='?plan_id='+encodeURIComponent(id),draftKey='webuddy.reform.edit.'+project+'.'+id,pendingKey=draftKey+'.pending';
  S.svc='reform';paintTabs('reform');setProj(project);paintSel();
  const alive=()=>route===location.hash&&seq===S.reformRead;
  let p;try{p=await get(base+query)}catch(e){if(!alive())return;$('#main').innerHTML=pageHead('改造计划','')+`<div class="empty" role="alert">${h(e.message)}<br><button id="rfRetryRead">重新加载</button></div>`;$('#rfRetryRead')?.addEventListener('click',()=>rfWorkspace(project,id,tab));return}
  if(!alive())return;
  const c=p.counts,canExecute=accessCanExecute(project),canWrite=accessCanWrite(project),closed=c.closed===c.total,cp=p.checkpoint;
  let draft;try{draft=JSON.parse(sessionStorage.getItem(draftKey)||'null')}catch(e){draft=null}
  const tabs=[['current','当前进展'],['tasks','批次与任务'],['recovery','接续与证据'],['scope','范围与历史']];
  const task=it=>`<article class="rf-task"><div class="row"><b class="grow">${h(it.title)}</b><span>${it.batch?'第 '+h(it.batch)+' 批':'尚未派发'}</span></div><p>${h(it.current?.label||'未放出')} · 负责人 ${h(it.current?.next_owner||p.next_owner)}</p>${it.ticket?`<a href="#/t/${encodeURIComponent(it.ticket)}">${h(it.ticket)} →</a>`:''}<p class="sub">${h(it.current?.next_action||'等待批次门槛')} · 证据 ${h(({valid:'当前有效',invalid:'已失效',not_checked:'待核对'})[it.evidence_validity]||'待核对')}</p>${it.current?.run_id?`<button class="ghost" onclick="showRun(${Number(it.current.run_id)})">运行 #${Number(it.current.run_id)} 与原始日志</button>`:''}${it.current?.candidate_commit?`<code>${h(it.current.candidate_commit)}</code>`:''}</article>`;
  const scope=()=>`<details open><summary>范围与约束 · 修订 ${h(p.revision)}</summary><h3>目标</h3><pre>${h(p.goal)}</pre><h3>不可变约束</h3><pre>${h(p.keep)}</pre><h3>验收标准</h3><ol>${(p.criteria||[]).map(x=>`<li>${h(x)}</li>`).join('')}</ol>${(p.dependencies||[]).length?`<h3>依赖与前置条件</h3><ul>${p.dependencies.map(x=>`<li>${h(x)}</li>`).join('')}</ul>`:''}${p.items.filter(x=>x.lead).map(x=>`<h3>先导部分：${h(x.title)}</h3><pre>${h(x.body)}</pre>`).join('')}${p.target?`<p>目标目录 ${h(p.target)}</p>`:''}<p>范围：${p.scope_mode==='all'?'全部业务域':h((p.domains||[]).join('、'))}</p><p>源版本 <code>${h(p.source_version||'旧计划未登记')}</code> · 环境 ${h(p.target_environment||'未登记')}</p></details>`;
  const actions=!p.archived&&!p.cancelled&&canExecute?`${p.paused?'':'<button data-rf-action="pause">暂停后续调度</button>'}${p.paused?'<button class="primary" data-rf-resume-preview>核对后继续</button>':!p.batch?'<button class="primary" data-rf-action="start">启动第一批</button>':!p.blocked&&(!closed||p.integration?.state==='missing')?'<button class="primary" data-rf-action="release_next">放出下一批</button>':''}<button data-rf-action="cancel">取消后续调度</button>`:'';
  let content=tab==='tasks'?p.items.map(task).join('')+(p.integrations||[]).map(x=>`<article class="rf-task"><h3>第 ${h(x.batch)} 批集成</h3><a href="#/t/${encodeURIComponent(x.ticket)}">${h(x.ticket)} →</a><p>${h(p.integration?.blocked||p.integration?.state||'待核对')}</p><code>${h(x.base)}</code></article>`).join(''):tab==='scope'?scope()+`${!c.released&&canWrite?`<details ${draft?'open':''}><summary>修订草稿</summary><form id="rfEdit"><label>名称<input name="title" value="${h(draft?.title??p.title)}" required></label><label>目标与范围<textarea name="goal" required>${h(draft?.goal??p.goal)}</textarea></label><label>不可变约束<textarea name="keep">${h(draft?.keep??p.keep)}</textarea></label><label>验收标准，每行一条<textarea name="criteria" required>${h(draft?.criteria??(p.criteria||[]).join('\n'))}</textarea></label><label>范围模式<select name="scope_mode"><option value="all" ${(draft?.scope_mode??p.scope_mode)==='all'?'selected':''}>全部业务域</option><option value="selected" ${(draft?.scope_mode??p.scope_mode)==='selected'?'selected':''}>选择部分业务域</option></select></label><label>业务域编号，用逗号分隔<input name="domains" value="${h(draft?.domains??(p.domains||[]).join(','))}"></label><label>修订原因<input name="reason" value="${h(draft?.reason||'')}" required></label><button class="primary">保存修订</button></form><div id="rfEditResult" role="status"></div></details>`:''}<details><summary>完整已保存历史（${(p.log||[]).length} 条）</summary>${(p.log||[]).map(e=>`<p>${h(chinaTime(e.at))} · ${h(e.text)}</p>`).join('')||'<p>暂无事件</p>'}${p.legacy_history_complete===false?'<p>旧版历史曾截断，当前保留原件；无法补造缺失事件。</p>':''}<details><summary>契约修订记录</summary>${(p.revisions||[]).map(r=>`<details><summary>修订 ${h(r.revision)} · ${h(r.reason)}</summary><pre>${h(JSON.stringify(r.contract,null,2))}</pre></details>`).join('')}</details></details>`:tab==='recovery'?`<h2>最近检查点</h2>${cp?`<p>#${h(cp.id)} · ${h(chinaTime(cp.created))} · ${h(cp.reason)}</p><code>${h(cp.source_commit)}</code><p>检查点仅保存真实版本引用，验证仍须按当前绑定核对。</p><details><summary>检查点保存内容</summary><pre>${h(JSON.stringify(cp,null,2))}</pre></details>`:'<p>暂无可核对的固定版本检查点。</p>'}<button data-rf-resume-preview>恢复预检</button><div id="rfPreflight" role="status"></div><h2>子任务证据</h2>${p.items.filter(x=>x.ticket).map(task).join('')||'<p>尚未派发任务。</p>'}`:`<h2>${h(p.batch_label)}</h2>${p.paused?`<p>${h(p.paused)}</p>`:''}${p.blocked?`<div class="rfpz">${h(p.blocked)}</div>`:'<p>当前没有已记录的调度阻塞。</p>'}${p.integration?.ticket?`<p>本批集成：<a href="#/t/${encodeURIComponent(p.integration.ticket)}">${h(p.integration.ticket)}</a> · ${h(p.integration.blocked||p.integration.state)}</p>`:''}<p>整体验证与业务决定：${p.evidence.integrated_delivery==='accepted'?'当前固定集成版本已整体验收':'尚未完成'}。${p.parent?`<a href="#/t/${encodeURIComponent(p.parent)}">整体验收入口 ${h(p.parent)} →</a>`:'子单关闭不代表计划已交付。'}</p>${p.items.filter(x=>x.batch===p.batch).map(task).join('')||'<p>准备开始第一批。</p>'}<h3>最近活动</h3>${(p.log||[]).slice(-5).reverse().map(e=>`<p>${h(chinaTime(e.at))} · ${h(e.text)}</p>`).join('')||'<p>尚无活动。</p>'}`;
  $('#main').innerHTML=`<div class="rf-workspace"><a href="#/reform">← 改造计划</a>${pageHead(p.title,'',`<button id="rfRefresh">刷新</button>`)}<p>${h(project)} · ${h(p.id)} · 修订 ${p.revision}${p.archived?' · 已归档':p.cancelled?' · 已取消':p.paused?' · 已暂停':''}</p><dl class="rf-summary"><div><dt>负责人</dt><dd>${h(p.next_owner)}</dd></div><div><dt>已派发</dt><dd>${c.released} / ${c.total}</dd></div><div><dt>已验收</dt><dd>${c.business_accepted} / ${c.total}</dd></div><div><dt>首次验收通过样本</dt><dd>${c.first_pass} / ${c.first_verdict_total}</dd></div><div><dt>最近检查点</dt><dd>${cp?'#'+cp.id:'未形成'}</dd></div></dl><div class="row" style="gap:8px">${actions}${(accessProjectRole(project)==='manager'||!S.meta.access)?'<button id="rfArchive">归档</button>':''}${sessionStorage.getItem(pendingKey)?'<button id="rfPending">核对上次操作</button>':''}</div><p id="rfSync" class="sub" role="status">最后同步 ${h(chinaTime(new Date().toISOString()))} · 状态更新 ${h(chinaTime(p.status_updated))}</p>${p.scheduling_reason?`<p class="sub">${h(p.scheduling_reason)} · 申请每批上限 ${h(p.wave)}，当前执行 ${h(p.effective_wave)}</p>`:''}<nav class="rf-nav" aria-label="改造计划内容">${tabs.map(([key,title])=>`<button data-rf-tab="${key}" aria-pressed="${tab===key}">${title}</button>`).join('')}</nav>${content}</div>`;
  const reload=()=>rfWorkspace(project,id,tab);
  $('#rfRefresh').onclick=reload;
  document.querySelectorAll('[data-rf-tab]').forEach(b=>b.onclick=()=>rfWorkspace(project,id,b.dataset.rfTab));
  async function mutate(body){sessionStorage.setItem(pendingKey,JSON.stringify(body));try{const result=await post(base+'/'+encodeURIComponent(id),body);sessionStorage.removeItem(pendingKey);if(alive()){toast(result.blocked||'操作已登记，请核对当前状态');reload()}}catch(e){if(alive())toast(e.message+'；请求号与原稿已保存，可核对上次操作',8000)}}
  const control=action=>mutate({action:'control',control_action:action,expected_revision:p.revision,request_id:crypto.randomUUID()});
  document.querySelectorAll('[data-rf-action]').forEach(b=>b.onclick=()=>control(b.dataset.rfAction));
  $('#rfArchive')?.addEventListener('click',()=>mutate({action:'archive',expected_revision:p.revision,request_id:crypto.randomUUID()}));
  $('#rfPending')?.addEventListener('click',()=>mutate(JSON.parse(sessionStorage.getItem(pendingKey))));
  document.querySelectorAll('[data-rf-resume-preview]').forEach(button=>button.addEventListener('click',async()=>{try{const value=await get(base+query+'&view=resume');if(!alive())return;if(!$('#rfPreflight')){const panel=document.createElement('div');panel.id='rfPreflight';$('#rfSync').after(panel)}$('#rfPreflight').innerHTML=`<h3>恢复预检</h3><p>${h(value.blocked||'当前无已记录阻塞')}</p><p>检查点：${h(value.checkpoint_accessibility)} · 下一责任人 ${h(value.next_owner)}</p><p>${h(value.retained)}</p><p>${h(value.revalidation)}</p><pre>${h(JSON.stringify(value.recovery_runs,null,2))}</pre>${value.allowed_actions.includes('resume')&&canExecute?'<button id="rfConfirmResume" class="primary">按当前条件继续计划</button>':''}`;$('#rfConfirmResume')?.addEventListener('click',()=>control('resume'))}catch(e){if(alive())toast(e.message)}}));
  const form=$('#rfEdit');if(form){const capture=()=>Object.fromEntries(new FormData(form)),originalRevision=draft?.expected_revision??p.revision;form.oninput=()=>sessionStorage.setItem(draftKey,JSON.stringify({...capture(),expected_revision:originalRevision}));form.onsubmit=async event=>{event.preventDefault();const fields=capture();sessionStorage.setItem(draftKey,JSON.stringify({...fields,expected_revision:originalRevision}));try{const domains=fields.domains.split(',').map(x=>x.trim()).filter(Boolean),preview=await post(base,{preview:true,scope_mode:fields.scope_mode,domains});const body={action:'update',expected_revision:originalRevision,request_id:crypto.randomUUID(),reason:fields.reason,changes:{title:fields.title,goal:fields.goal,keep:fields.keep,criteria:fields.criteria.split('\n').filter(x=>x.trim()),scope_mode:fields.scope_mode,domains,knowledge_revision:preview.knowledge_revision}};sessionStorage.setItem(pendingKey,JSON.stringify(body));const result=await post(base+'/'+encodeURIComponent(id),body);sessionStorage.removeItem(pendingKey);sessionStorage.removeItem(draftKey);if(alive()){toast('修订已保存');reload()}}catch(e){if(!alive())return;$('#rfEditResult').textContent=e.message+'；原稿已保留。';let latest;try{latest=await get(base+query)}catch(readError){if(alive())$('#rfEditResult').textContent+=' 当前服务端修订暂不可读：'+readError.message;return}if(!alive())return;$('#rfEditResult').innerHTML=`<p>${h(e.message)}；原稿已保留。</p><div class="rf-conflict"><div><h3>当前服务端修订 ${latest.revision}</h3><pre>${h(JSON.stringify({goal:latest.goal,keep:latest.keep,domains:latest.domains,criteria:latest.criteria},null,2))}</pre></div><div><h3>本地草稿（基于修订 ${originalRevision}）</h3><pre>${h(JSON.stringify(fields,null,2))}</pre></div></div><button id="rfRebaseDraft">按当前修订重新编辑，保留本地内容</button>`;$('#rfRebaseDraft').onclick=()=>{sessionStorage.setItem(draftKey,JSON.stringify({...fields,expected_revision:latest.revision}));sessionStorage.removeItem(pendingKey);reload()}}}}
  let polling=false;poll(async()=>{if(!alive()||polling||sessionStorage.getItem(draftKey))return;polling=true;try{const next=await get(base+query);if(!alive())return;if(JSON.stringify(next)!==JSON.stringify(p)){reload();return}$('#rfSync').textContent='最后同步 '+chinaTime(new Date().toISOString())+' · 状态更新 '+chinaTime(next.status_updated)}catch(e){if(alive())$('#rfSync').textContent='同步失败：'+e.message+'；保留当前内容'}finally{polling=false}},5000,'reform-detail');
}
"""
